    """DP over physical title counts (no canonical sorting) - unambiguous."""
    @lru_cache(maxsize=None)
    def dp(c, groups):
        c = tuple(c)
        if all(x == 0 for x in c):
            return 0, []
        nz = [i for i in range(5) if c[i] > 0]
