                for i in subset:
                    nc[i] -= 1
                v, sub = dp(nc, None)
                v += group_cost[s]
                if best is None or v < best[0]:
                    best = (v, [[i + 1 for i in subset]] + sub)
        return best
    return dp(list(counts), None)

