import itertools
from functools import lru_cache

group_cost = [0, 800, 1520, 2160, 2560, 3000]

def opt_sizes(counts):
    @lru_cache(maxsize=None)
    def dp(c):
        if c == (0, 0, 0, 0, 0):
            return 0, ()
        nz = [i for i in range(5) if c[i] > 0]
        best = None
        for s in range(1, min(5, len(nz)) + 1):
            for subset in itertools.combinations(nz, s):
                nc = list(c)
                for i in subset:
                    nc[i] -= 1
                nc.sort(reverse=True)
                v, gs = dp(tuple(nc))
                v += group_cost[s]
                if best is None or v < best[0]:
                    best = (v, (s,) + gs)
        return best
    return dp(tuple(sorted(counts, reverse=True)))

